message.content:
{
  "candidate_edge_types": [
    {
      "name": "FAILED_COMMAND_TRIGGERS_CORRECTIVE_ACTION",
      "definition": "A command execution failure observed by the agent causes a subsequent agent action that reformulates or corrects the command to accomplish the intended operation.",
      "source_description": "An observed failed command execution, such as an invalid option or syntax error.",
      "target_description": "A subsequent agent action that adjusts the command invocation to resolve the failure."
    },
    {
      "name": "OBSERVED_DOCUMENT_CONTENT_INFORMS_CLASSIFICATION",
      "definition": "An agent inspects document content obtained from an earlier extraction or listing result and uses that content to classify the document into a task-relevant category such as invoice or other.",
      "source_description": "An execution observation containing document content or extracted text.",
      "target_description": "An agent classification decision assigning a document to a category."
    },
    {
      "name": "OBSERVED_INVOICE_CONTENT_INFORMS_AMOUNT_EXTRACTION",
      "definition": "An agent inspects invoice content and uses observed monetary or tax fields to extract one or more required amounts, such as total amount or VAT amount.",
      "source_description": "An execution observation containing invoice text with monetary or tax fields.",
      "target_description": "An agent amount-extraction decision recording a total amount or VAT amount from that invoice."
    },
    {
      "name": "CONFLICTING_AMOUNT_FIELDS_TRIGGER_RULE_BASED_SELECTION",
      "definition": "An agent observes multiple candidate total-amount fields with differing values in the same document and applies a specified precedence rule to select the correct one, such as using Total over Amount Due.",
      "source_description": "An observation showing multiple conflicting candidate total-amount fields in a document.",
      "target_description": "An agent selection decision that chooses one amount according to the task's precedence rule."
    },
    {
      "name": "MISSING_REQUIRED_AMOUNT_FIELD_TRIGGERS_DEFAULT_ASSIGNMENT",
      "definition": "An agent observes that a required amount field, such as VAT or tax, is absent from invoice content and assigns the task-specified default value of zero or an empty string.",
      "source_description": "An observation of invoice content that lacks a required amount field such as VAT, tax, or GST.",
      "target_description": "An agent decision assigning the default value to the missing amount field."
    },
    {
      "name": "CLASSIFICATION_RESULT_SCOPES_AMOUNT_EXTRACTION",
      "definition": "A prior document classification decision determines which documents are targeted for subsequent amount-field extraction, such as extracting totals and VAT only from documents classified as invoices.",
      "source_description": "An agent classification decision labeling a document as a type that requires downstream amount extraction.",
      "target_description": "A subsequent amount-extraction action directed at that classified document."
    },
    {
      "name": "PREVIOUSLY_PRODUCED_ARTIFACT_USED_AS_INPUT_FOR_INSPECTION",
      "definition": "A previously produced artifact, such as an extracted text file, is consumed as input by a subsequent inspection command to read or examine its contents.",
      "source_description": "A previously produced result or artifact available in the execution environment.",
      "target_description": "A subsequent agent action that reads or inspects that artifact."
    }
  ]
}

